import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';

const VILLES = ['Tunis', 'Sfax', 'Sousse', 'Monastir', 'Nabeul', 'Bizerte', 'Kairouan', 'Ariana', 'Ben Arous', 'Mahdia'];
const NIVEAUX = ['Primaire', 'Collège 1ère', 'Collège 2ème', 'Collège 3ème', 'Lycée 1ère', 'Lycée 2ème', 'Lycée 3ème (Bac)', 'Université L1', 'Université L2', 'Université L3', 'Master'];

export default function Profile() {
  const { user } = useAuth();
  const [form, setForm] = useState({
    user_prenom: '', user_nom: '', email: '', ville: '', bio: '', telephone: '',
    niveau: '', tarifs_matieres: [], certificats: [], photo_url: null
  });
  const [availableMatieres, setAvailableMatieres] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saved, setSaved] = useState(false);

  // États pour les modales
  const [showCertModal, setShowCertModal] = useState(false);
  const [newCert, setNewCert] = useState({ titre: '', description: '' });
  const [selectedFile, setSelectedFile] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
        const res = await api.get(route);
        setForm(res.data);

        if (user?.role === 'professeur') {
          const resMat = await api.get('/api/admin/referentiel/matieres');
          setAvailableMatieres(resMat.data);
        }
        setLoading(false);
      } catch (e) { 
        console.error("Erreur chargement profil");
        setLoading(false);
      }
    };
    fetchData();
  }, [user]);

  // --- 1. PHOTO DE PROFIL ---
  const handlePhotoUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/api/professeurs/me/photo', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setForm({ ...form, photo_url: res.data.url });
      alert("✅ Photo mise à jour !");
    } catch (e) { alert("Erreur lors de l'envoi de la photo"); }
  };

  // --- 2. CERTIFICATS (Image 2) ---
  const handleCertUpload = async (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('titre', newCert.titre);
    formData.append('description', newCert.description);
    formData.append('file', selectedFile);
    try {
      await api.post('/api/professeurs/me/certificats', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setShowCertModal(false);
      window.location.reload(); 
    } catch (e) { alert("Erreur upload certificat"); }
  };

  // --- 3. MATIÈRES & TARIFS (Image 3 & 4) ---
  const handleToggleMatiere = (matiere_id) => {
    let updated = [...(form.tarifs_matieres || [])];
    const index = updated.findIndex(t => t.matiere_id === matiere_id);
    if (index > -1) {
      updated = updated.filter(t => t.matiere_id !== matiere_id);
    } else {
      updated.push({ matiere_id, tarif: 20 });
    }
    setForm({ ...form, tarifs_matieres: updated });
  };

  const handleTarifChange = (matiere_id, val) => {
    const updated = form.tarifs_matieres.map(t => 
      t.matiere_id === matiere_id ? { ...t, tarif: parseFloat(val) || 0 } : t
    );
    setForm({ ...form, tarifs_matieres: updated });
  };

  // --- 4. SAUVEGARDE GLOBALE ---
  async function handleSave() {
    try {
      const route = user?.role === 'professeur' ? '/api/professeurs/me' : '/api/etudiants/me';
      const payload = {
        nom: form.user_nom,
        prenom: form.user_prenom,
        ville: form.ville,
        niveau: form.niveau,
        telephone: form.telephone,
        bio: form.bio,
        matieres_avec_tarifs: form.tarifs_matieres
      };
      await api.put(route, payload);
      setSaved(true); setTimeout(() => setSaved(false), 2000);
    } catch (e) { alert('Erreur lors de la sauvegarde'); }
  }

  const inp = { background: 'var(--surface2)', border: '1px solid var(--border)', borderRadius: 10, color: 'var(--text)', padding: '10px 14px', fontSize: '.88rem', outline: 'none', width: '100%' };

  if (loading) return <div style={{padding: 50, textAlign: 'center', color: 'var(--accent)'}}>Chargement de votre univers...</div>;

  return (
    <div style={{ padding: 32, maxWidth: 1200, margin: '0 auto' }}>

      {/* SECTION HEADER */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 30, marginBottom: 32, background: 'var(--card)', padding: 24, borderRadius: 24, border: '1px solid var(--border)' }}>
        <div style={{ position: 'relative' }}>
          <div style={{ width: 110, height: 110, borderRadius: '50%', overflow: 'hidden', border: '3px solid var(--accent)', background: 'var(--surface2)' }}>
            <img src={form.photo_url ? `http://localhost:8001${form.photo_url}` : 'https://ui-avatars.com/api/?name=' + form.user_prenom} alt="Avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>
          {user?.role === 'professeur' && (
            <label style={{ position: 'absolute', bottom: 5, right: 5, background: 'var(--accent)', width: 32, height: 32, borderRadius: '50%', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', border: '2px solid var(--card)' }}>
              📷 <input type="file" hidden onChange={handlePhotoUpload} />
            </label>
          )}
        </div>
        <div>
          <h2 style={{ fontFamily: 'Syne', fontSize: '1.8rem' }}>{form.user_prenom} {form.user_nom}</h2>
          <p style={{ color: 'var(--text2)' }}>{form.email} • <span style={{ color: 'var(--accent)' }}>Compte {user?.role}</span></p>
          {user?.role === 'professeur' && <span style={{ background: form.statut_validation === 'validé' ? 'rgba(67,233,123,0.15)' : 'rgba(255,101,132,0.15)', color: form.statut_validation === 'validé' ? '#43e97b' : '#ff6584', padding: '4px 12px', borderRadius: 20, fontSize: '.75rem', fontWeight: 700 }}>{form.statut_validation?.toUpperCase()}</span>}
        </div>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: user?.role === 'professeur' ? '1fr 1fr' : '1fr', gap: 30 }}>

        {/* COLONNE 1 : IDENTITÉ & INFOS */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 24 }}>
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 20, fontSize: '1.1rem' }}>👤 Informations personnelles</h3>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 15, marginBottom: 15 }}>
               <div><label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Prénom</label><input style={inp} value={form.user_prenom || ''} onChange={e => setForm({...form, user_prenom: e.target.value})} /></div>
               <div><label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Nom</label><input style={inp} value={form.user_nom || ''} onChange={e => setForm({...form, user_nom: e.target.value})} /></div>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 15, marginBottom: 15 }}>
               <div>
                  <label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Ville</label>
                  <select style={inp} value={form.ville || ''} onChange={e => setForm({...form, ville: e.target.value})}>
                    <option value="">Choisir...</option>
                    {VILLES.map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
               </div>
               <div>
                  <label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Téléphone</label>
                  <input style={inp} placeholder="+216" value={form.telephone || ''} onChange={e => setForm({...form, telephone: e.target.value})} />
               </div>
            </div>
            {user?.role === 'étudiant' && (
              <div style={{marginBottom: 15}}>
                <label style={{fontSize: '.8rem', color: 'var(--text2)'}}>Niveau scolaire actuel</label>
                <select style={inp} value={form.niveau || ''} onChange={e => setForm({...form, niveau: e.target.value})}>
                  <option value="">Sélectionner mon niveau</option>
                  {NIVEAUX.map(n => <option key={n} value={n}>{n}</option>)}
                </select>
              </div>
            )}
            <button onClick={handleSave} style={{ width: '100%', background: 'var(--accent)', color: '#fff', border: 'none', padding: 14, borderRadius: 12, fontWeight: 600, cursor: 'pointer', marginTop: 10 }}>
              {saved ? '✅ Modifications enregistrées' : 'Mettre à jour mon profil'}
            </button>
          </div>

          {/* CERTIFICATS (Pour Profs) */}
          {user?.role === 'professeur' && (
            <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
                <h3 style={{ marginBottom: 16, fontSize: '1.1rem' }}>📜 Diplômes & Certificats</h3>
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
                    {form.certificats?.map(c => (
                        <div key={c.id} style={{ background: 'var(--surface2)', padding: 12, borderRadius: 12, border: '1px solid var(--border)' }}>
                            <div style={{ fontWeight: 600, fontSize: '.85rem' }}>{c.titre}</div>
                            <a href={`http://localhost:8001${c.fichier_url}`} target="_blank" rel="noreferrer" style={{ color: 'var(--accent)', fontSize: '.75rem' }}>Visualiser ↗</a>
                        </div>
                    ))}
                    <div onClick={() => setShowCertModal(true)} style={{ border: '2px dashed var(--border)', borderRadius: 12, padding: 20, cursor: 'pointer', textAlign: 'center', color: 'var(--accent)', fontSize: '.85rem' }}>+ Ajouter</div>
                </div>
            </div>
          )}
        </div>

        {/* COLONNE 2 : MATIÈRES (Pour Profs) */}
        {user?.role === 'professeur' && (
          <div style={{ background: 'var(--card)', border: '1px solid var(--border)', borderRadius: 20, padding: 24 }}>
            <h3 style={{ marginBottom: 10, fontSize: '1.1rem' }}>📚 Mes Matières & Tarifs</h3>
            <p style={{ color: 'var(--text2)', fontSize: '.85rem', marginBottom: 20 }}>Sélectionnez vos matières et fixez votre prix par heure.</p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: 10, maxHeight: 500, overflowY: 'auto', paddingRight: 10 }}>
                {availableMatieres.map(m => {
                    const active = form.tarifs_matieres?.find(t => t.matiere_id === m.id);
                    return (
                        <div key={m.id} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '12px 16px', background: active ? 'rgba(108,99,255,0.08)' : 'transparent', borderRadius: 12, border: active ? '1px solid var(--accent)' : '1px solid var(--border)' }}>
                            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
                                <input type="checkbox" style={{ width: 18, height: 18 }} checked={!!active} onChange={() => handleToggleMatiere(m.id)} />
                                <span style={{ fontWeight: active ? 600 : 400 }}>{m.nom}</span>
                            </div>
                            {active && (
                                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                                    <input type="number" value={active.tarif} onChange={e => handleTarifChange(m.id, e.target.value)} style={{ ...inp, width: 70, textAlign: 'center' }} />
                                    <span style={{ fontSize: '.75rem', fontWeight: 600 }}>DT/H</span>
                                </div>
                            )}
                        </div>
                    )
                })}
            </div>
          </div>
        )}
      </div>

      {/* MODALE CERTIFICAT */}
      {showCertModal && (
        <div style={{ position: 'fixed', inset: 0, background: 'rgba(0,0,0,0.8)', zIndex: 1000, display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
            <div style={{ background: 'var(--surface)', padding: 30, borderRadius: 24, width: 400, border: '1px solid var(--border)' }}>
                <h3 style={{ marginBottom: 20 }}>Ajouter un certificat</h3>
                <form onSubmit={handleCertUpload}>
                    <input style={{...inp, marginBottom: 15}} placeholder="Titre du diplôme" onChange={e => setNewCert({...newCert, titre: e.target.value})} required />
                    <textarea style={{...inp, marginBottom: 15, height: 80}} placeholder="Description" onChange={e => setNewCert({...newCert, description: e.target.value})} />
                    <input type="file" style={{marginBottom: 20}} onChange={e => setSelectedFile(e.target.files[0])} required />
                    <div style={{ display: 'flex', gap: 10 }}>
                        <button type="submit" style={{ flex: 1, background: 'var(--accent)', color: '#fff', border: 'none', padding: 12, borderRadius: 12, fontWeight: 600 }}>Enregistrer</button>
                        <button type="button" onClick={() => setShowCertModal(false)} style={{ flex: 1, background: 'var(--surface2)', color: '#fff', border: 'none', padding: 12, borderRadius: 12 }}>Annuler</button>
                    </div>
                </form>
            </div>
        </div>
      )}
    </div>
  );
}
